@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1016  cases=31
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-125
  @fn seedItems(h, takes, srcLen)  @ 141-146
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 148-157

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 161-169
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 172-181
  @case 'focusState before any render returns both bits false'  [harness]  @ 184-191
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 197-210
  @case 'with no live instance, new take and unpooled duplicate mint a parked slot and select it'  [harness]  @ 214-236
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 242-260
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 267-285
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 291-324
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 328-352
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 358-388
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 392-413
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 417-430
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 434-457
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 464-481
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 485-508
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 512-535
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 539-574
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 578-594
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 601-628
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 632-656
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 663-684
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 690-708
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 712-730
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 734-756
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 760-784
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 790-845
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 853-882
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 888-931
  @case 'empty grid shows the single no-takes message'  [harness]  @ 937-951
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 958-990
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 994-1014

